int countWordOccurrences(std::ifstream& file, const std::string& word) {
   int wordCount = 0;
   std::string line;

   while (std::getline(file, line)) {
      size_t pos = 0;
      while ((pos = line.find(word, pos)) != std::string::npos) {
         wordCount++;                // Increment count for each occurrence
         pos += word.length();       // Skip matched word when searching for next occurrence
      }
   }
   return wordCount;
}
